["Add or remove the selected quest from your quest watch list. You can click on a quest in your quest watch list to see the details of that quest."]="Adiciona ou remove a missão selecionada do seu seguimento de missões. Você pode clicar em uma missão da lista para ver os detalhes dessa missão.",
