["Additionally, we encourage all players to first utilize the forums and the website to pursue information about their respective issues at |cffffd200www.worldofwarcraft.com|r , and request that specific attention be paid to our game policies at |cffffd200www.worldofwarcraft.com/policy/|r ."]="Além disso, encorajamos todos os jogadores a utilizarem os fóruns e o site (|cffffd200www.wow-europe.com/es/|r) para documentarem-se sobre seus problemas e pedimos que prestem especial atenção às nossas políticas do jogo (|cffffd200www.wow-europe.com/es/policy/|r).",
["Adds a new player to the guild."]="Adiciona um novo jogador à guild.",
["Adds a new player to the team."]="Adiciona um novo jogador ao computador.",
["Adds a player to your friends list. You will be notified whenever a friend logs on or off. Other players do not know whether they are on your friends list."]="Adiciona um jogador à sua lista de amigos. Você receberá uma notificação quando seus amigos se ligarem ou desconecten. Os outros jogadores não saberão se estão ou não na sua lista de amigos.",
["Adds a player to your ignore list. You will no longer see messages or other text from players on your ignore list, nor will these players be able to communicate with you in any other way."]="Adiciona um jogador à sua lista de ignorados. Você não poderá ver mensagens ou texto de jogadores na sua lista de ignorados, nem eles também poderão comunicar com você de forma alguma.",
["Adds a player to your mute list. You will no longer hear voice chat from players on your mute list."]="Adiciona um jogador à sua lista de jogadores em Silêncio. Você não o ouvirá o chat de voz dos que adicionarem a esta lista.",
["Adds to your Attack Power, Damage-Per-Second. Strength\ndoes not affect Critical Hit chances at all. Strength does\nnot improve your chance to block, but rather the amount\nblocked when you succeed. This amount is determined in\npart by Strength (and the other part by your shield). "]="Aumenta o seu poder de ataque, dano por segundo. A força\nNão afecta de forma alguma a probabilidade de impacto crítico.\nAs suas probabilidades de bloquear, mas a quantidade de pontos\nEles bloquearam o seu sucesso. Este montante é determinado em parte por\na força (e por outro lado, pelo seu escudo).",
