["Check my breath.  Is it bad enough for you?"]="O que acha de meu fôlego? É o bastante apestoso para você?",
["Check this box to override your language setting and use english audio."]="Marca esta caixa para sobrepor a sua configuração de idioma e usar o áudio em inglês.",
["Check this option to always display extra actionbars."]="Ativa esta opção para mostrar sempre as barras de ação adicionais.",
["Check this option to automatically join the Guild Recruitment chat channel based upon whether or not you are in a guild."]="Ativa esta opção para se juntar ao canal de bate-papo de recrutamento de guilds automaticamente, dependendo de se você está ou não já em uma guild.",
["Check this to be able to list the quests in any order you want."]="Ativa esta opção para ver as missões na ordem que quiser.",
["Check this to enable dynamic reduction of terrain polygon detail.  Check to increase performance."]="Esta opção serve para ativar a redução dinâmica dos detalhes poligonais do terreno. A Actívala é capaz de aumentar o desempenho.",
["Check this to make quest text appear instantly."]="Ativa esta opção para aparecer o texto das missões de forma instantânea.",
["Check this to rotate the entire minimap instead of the player arrow."]="Ativa esta opção para rodar o minimapa inteiro em vez da seta do jogador.",
["Check this to show threat on targets as a percentage."]="Ativa esta opção para mostrar a ameaça em objetivos como uma percentagem.",
["Check this to sort quests by the distance from their map locations to you."]="Ativa esta opção para ordenar as missões por distância.",
["Check this to sort quests in decreasing order of difficulty."]="Ativa esta opção para ordenar as missões por dificuldade descendente.",
["Check this to sort quests in increasing order of difficulty."]="Ativa esta opção para ordenar as missões por dificuldade ascendente.",
["Check to make the mouse wheel scroll through chat when the cursor is over a chat window."]="Active isto para fazer com que a roda do rato deslogue o chat quando o cursor estiver numa janela de chat.",
["Check to maximize window and remove borders."]="Ativa esta opção para maximizar a janela e remover os contornos.",
["Check to play in a non-fullscreen window.\n\nIf this is checked the game will use your desktop gamma and you will not be able to adjust it via the slider below."]="Assinale esta opção para jogar numa janela que não ocupe todo o tela.\n\nSi tem esta opção assinalada, o jogo irá usar o brilho do tela e não poderá ser ajustado com a barra inferior.",
["Check to show chat windows immediately upon mouseover."]="Ativa esta opção para mostrar a janela de chat imediatamente ao passar por cima do rato.",
["Check to track this achievement."]="Marca a realização para acompanhar.",
["Check to use the UI Scale Slider, uncheck to use the system default scale."]="Coloque uma marca para usar a barra deslizante para ajustar o tamanho da interface do usuário. Remover a marca para usar o tamanho por omissão.",
["Checking this option will allow you to track this currency type on your backpack.\n\nYou can also Shift-click a currency to add or remove it from your backpack."]="Se você escolher esta opção, você poderá acompanhar esta moeda na sua mochila.\n\nTambém pode fazer Shift+clic numa moeda para adicionar a sua mochila ou removê-la.",
["Checking this will enable additional combat messages to appear in the playfield."]="Se ativar esta opção, irão aparecer mensagens de combate adicionais no jogo.",
["Checking this will hide the interface for tracking zone wide objectives."]="Se ativar esta opção, a interface será escondida para rastrear objetivos em áreas extensas.",
["Checking this will prevent the deselection of targets by clicking on the gamefield.  Targets can only be cleared by pressing escape or clicking another target."]="Se assinalar esta opção, você irá evitar remover a selecção de um objetivo ao clicar no campo de jogo. Você só poderá remover uma selecção se carregar na tecla Esc ou se seleccionar outro objetivo.",
["Checking this will show any selected auction items on your character.\n\nCTRL-Left Clicking any equippable item in the game will also allow you to try it on your character."]="Se ativar esta opção, todos os objetos selecionados serão apresentados para leilão.\n\nSi, se carregar com o botão esquerdo enquanto carregar em Control num objeto que possa ser equipado, poderá também tentar o seu personagem.",
