["Congratulations! You just gained a level and became more powerful.|n|nYou can visit your class trainer and see if he or she has new abilities that you can learn."]="Você acabou de obter um nível e tornou-se mais poderoso.|n|n pode ir ver seu instrutor de classe para saber se há novas habilidades que você possa aprender.",
["Congratulations, you have learned how to summon your first mount. This mighty steed will carry you throughout your adventures in Azeroth and beyond.|n|nTo see all of your mounts, click the |cffffd200Character Info Button|r and look for the Pets tab. You can drag your favorite mount onto your action bar to summon it more easily."]="Parabéns, você aprendeu a invocar a sua primeira montura. Este poderoso corcel levará você de aventura em aventura pelas terras de Azeroth e além.|n|n|nPara ver todas as suas armações, consulta a página Massas dentro do |cffffd200botão de informação de personagem|r. Você poderá arrastar a sua montura favorita à barra de ação para invocar com maior facilidade.",
["Congratulations, you have received your first companion. This little fellow will follow you during all of your adventures in Azeroth and beyond.|n|nYou can see all of your companions by clicking the |cffffd200Character Info Button|r and then looking for the Pets tab."]="Parabéns, você recebeu seu primeiro companheiro. Este amiguinho vai seguir você em todas as suas aventuras por Azeroth e além.|n|nVocê pode ver todos os seus companheiros na página Mascotes do |cffffd200botão de informações do personagem|r.",
["Congratulations."]="Parabéns.",
["Conjured Item"]="Objeto mágico",
["Connection lost to Voice Chat service."]="Perdeu-se a ligação com o serviço de bate-papo de voz.",
["Connection/disconnection problems"]="Problemas de ligação/desligação",
["Consecutive silent characters are not allowed. Create a new name."]="Não são permitidos caracteres silenciosos consecutivos. Cria um novo nome.",
["Consecutive spaces are not allowed.  Enter a new name."]="Não são permitidos espaços consecutivos. Escreva outro nome.",
