["Continue"]="Continuar",
["Controls"]="Controlos",
["Controls how far you can see objects. Decrease to improve performance."]="Controla a visão de objetos de longe. Disminue-a para aumentar o desempenho.",
["Controls the brightness of the game. Increase brightness until you can clearly see all 21 levels of gray bars below."]="Controla o brilho do jogo. Aumenta o brilho até ver os 21 tons de barras cinzentas abaixo com clareza.",
["Controls the detail level of spell effects.  Decrease to improve performance."]="Controla o nível dos detalhes dos efeitos dos feitiços. Diminui o nível para aumentar o desempenho.",
["Controls the draw distance of ground clutter items like grass and foliage.  Decrease to improve performance."]="Controla a distância entre os detalhes do solo como a erva ou a folhagem. Diminui a distância para melhorar o desempenho.",
["Controls the intensity of weather effects.  Decrease to improve performance."]="Controla a intensidade dos efeitos atmosféricos. Diminui a intensidade para melhorar o desempenho.",
["Controls the level of all texture detail. Decreasing this may slightly improve performance."]="Controla o nível de detalhe de todas as texturas. Se o diminuir, poderá aumentar ligeiramente o desempenho.",
["Controls the movie quality. This will affect the final compression. Increasing the quality will also increase the amount of disk space used by the movie and the compression speed."]="Controla a qualidade do vídeo. Afectará a compressão final. Se você aumentar a qualidade do vídeo, também aumentará o espaço que irá ocupar no seu disco rígido e a velocidade de compressão.",
["Controls the number of ground clutter items, like grass and foliage.  Decrease to improve performance."]="Controla o número de detalhes do solo como a erva ou a folhagem. Diminui o seu número para melhorar o desempenho.",
["Controls the number of particles used in effects caused by spells, fires, etc. Decrease to improve performance."]="Controla a quantidade de partículas utilizadas para efeitos de feitiços, fogo e outros. Diminui a densidade para melhorar o desempenho.",
["Controls the quality of rendered character and environment shadows. Decrease to improve performance."]="Controla a qualidade de renderização das sombras de personagens e do ambiente. Diminui a qualidade para melhorar o desempenho.",
["Controls the resolution of player textures. Decreasing this may slightly improve performance."]="Controla a resolução das texturas de personagem. Se a diminuir, poderá aumentar ligeiramente o desempenho.",
["Controls whether or not icon links in auto-joined chat channels (such as Trade) are displayed as icons."]="Controla se os links de ícones são mostrados como ícones ou não nos canais de chat automáticos (como o Comércio).",
