["Enable mature language filtering.\n\n|cffff0000Warning:|r Battle.net is unavailable, so this setting may not be saved."]="Ativa o filtro de linguagem adulto.\n\n|cffff0000Advertência:|r Battle.net não está disponível, pelo que pode não ser gravada esta mudança.",
["Enable the playing of alert sounds when aggro advances to a higher level."]="Ativa os sons que alertam para a subida de ameaça.",
["Enable this option for a more responsive cursor unless you have cursor problems."]="Ativa esta opção para obter melhor resposta do cursor, a menos que tenha problemas com o cursor.",
["Enable this option for smooth lighting across characters."]="Ativa esta opção para suavizar as luzes dos personagens.",
["Enable this option if you have a World of Warcraft Gaming Mouse and you wish to bind keys to the extra buttons."]="Ativa esta opção se tiver o World of Warcraft Gaming Mouse e quiser atribuir ações aos botões extra.",
