["For assistance with any issues like these, please contact Billing & Account Services:|n|nBy Phone at:  |cffffd200(800) 59-BLIZZARD|r|nBy Web at:  |cffffd200http://us.blizzard.com/support/index.xml?gameId=11|r|nBy Email at:  |cffffd200billing@blizzard.com|r |n|nWe also recommend you check the Account Management page at: |n|n|cffffd200www.worldofwarcraft.com/account|r |n|nOn the Account Management page, you can view your subscription information, add game cards, and access other important account functions and options."]="Para obter assistência com qualquer um destes problemas, por favor, entre em contato com o departamento de faturamento:|n|nPor telefone: |cffffd200800 099 812|r|nA através do nosso site: |cffffd200http://www.wow-europe.com/es/support/accountbilling.html|r|nPor e-mail: |cffffd200wowbillingsupportEU@blizzard.com|r |n|nAsimismo, recomendamos que você eches um olho para a sua página de gestão de conta: |n|n|cffffd200www.wow-europe.com/login/|r |n|nAllí você possa ver informações sobre sua assinatura, adicionar cartões pré-pago e acessar outro tipo de funções e opções de conta.",
