["Game Masters are normally available to assist 24 hours a day. The next available Game Master will be able to assist you no matter which character you are currently playing on.  Please keep in mind wait times may vary, and there are some issues that Game Masters will |cffffd200NOT|r be able to assist you with.  Those issues include, but are |cffffd200NOT|r limited to the following:"]="Normalmente, os professores de jogo estão disponíveis para ajudá-lo 24 horas por dia. O professor de jogo que está disponível irá ajudá-lo sem importar o personagem com o qual você está jogando. Lembre-se que os tempos de espera podem variar e que existem alguns temas com os quais os professores de jogo |cffffd200NO|r poderão ajudá-lo, incluindo mas |cffffd200NO|r se limitando a:",
