["Honor Points"]="Pontos de honra",
["Honor is gained by killing members of the opposite faction in PvP combat. You can use honor points to purchase special items."]="Ganha pontos de honra ao matar membros da facção inimiga em combates JcJ. Usa estes pontos para adquirir objetos especiais.",
["Honor is what you gain by making honorable kills in PvP combat.   How much honor you gain per kill is determined by how much damage you (or your group) did to the player that was killed, with more damage done equaling more honor.   This honor gain is split amongst the members of your group or raid group.   Also you will gain less honor for killing the same player over and over again in a short period of time, so after a few kills of the same player you will get little or no honor from killing them."]="Ganhas honra matando com honra durante os combates entre jogadores (JcJ). A quantidade de honra que ganha por morte depende do dano que você (ou seu grupo) infligiu ao jogador removido. Quanto mais danos lhe inflijas, mais honra você receberá. A honra obtida será dividida entre os membros do grupo ou da banda. Além disso, ganhará menos honra se vontade ao mesmo jogador uma e outra vez em pouco tempo. Assim, depois de matar o mesmo jogador várias vezes, você receberá muito menos ou deixará de receber honra.",
["Honor required it."]="A honra o requeria.",
