["Horn Style"]="Estilo chifres",
["Hostile"]="Hostil",
["Hot Issue"]="Tema Candente",
["How are you?"]="Como você está?",
["How does a Tauren hide in a cherry tree?  He paints his hooves red."]="Como se esconde um touro em um cerezo? Ele pinta as unhas de vermelho.",
["How generous."]="Que generosidade.",
["How kind of you."]="Que amável és.",
["How much memory your AddOns are using. You can get to the addon management page from the character select screen."]="Quantidade de memória que usam os seus addons. Aceder à página de gestão de Acessórios do tela de seleção de personagem.",
["How you doing?"]="Como você está?",
["How's it hanging?"]="Que tal te vai?",
["Hunters require focus to use their abilities.  Focus generates while standing still."]="Os caçadores precisam de abordagem para usar suas habilidades. A abordagem é gerada ao ficar quieto.",
["Hurry, fire!"]="Fogo! Depressa!",
["I am in your debt."]="Eu te devo uma.",
["I apologize profusely for any inconvenience my murderous rampage may have caused."]="Peço desculpa por qualquer inconveniente que possa ter causado o massacre em que me vi envolta.",
["I be feeling you."]="Estamos de acordo.",
["I be in a bad way!"]="Estou mal!",
["I be in a bad way."]="Estou mal!",
["I be needing more mana!"]="Eu preciso de mais maná!",
["I believe so."]="Acho que sim.",
["I can fulfill the role of:"]="Posso desempenhar o papel de:",
["I can't find anywhere to get my nails done."]="Preciso de uma pedicura com urgência.",
["I can't stand the smell of Orcs."]="Não suporto o cheiro dos orcos.",
["I can't wait till this quest is done, and I can look for another Garibaldi artifact."]="Que vontade tenho de acabar esta missão e poder procurar outro objeto Garibaldi.",
["I can't wait to suck the juice out of your eyeballs."]="Que vontade tenho de chuparte as bacias dos olhos.",
["I come from the Orcs.  We eat with spoons and forks.  We love to eat our pork."]="Venho dos orcos. Comemos com colheres e garfos e adoramos comer porco.",
["I dig it."]="Estou de acordo.",
["I do hope to find some interesting gadgets around here.  I do love tinkering with things."]="Espero encontrar alguns artilugios interessantes por aqui. Adoro tecer com cacharros.",
["I do not find you completely disagreeable."]="Não me pareces totalmente desagradável.",
["I don't care that much about romance.  I fell in love before, and look what happened to me."]="Não me interessa muito o romantismo. Apaixonei-me uma vez e olha o que me aconteceu.",
["I don't drink anymore.  'Course, I don't drink any less, either."]="Eu deixo de beber entre trago e bebida.",
["I don't feel that the 1 to 10 scale is fine enough to capture subtle details of compatibility.  I'd prefer a 12 dimensional compatibility scale with additional parameters for mechanical aptitude and torque."]="Não me parece que a escala de 1 a 10 seja suficiente para capturar pequenos detalhes de compatibilidade. Preferiria uma escala de compatibilidade dimensional de 12 com parâmetros adicionais para a aptidão mecânica e de torção.",
["I don't have a drinking problem.  I drink, I get drunk, I fall down, no problem."]="Não tenho problemas com o álcool. Bebo, estou enborracho, estou me caigo e ponto.",
["I don't know about you, but I can't understand a thing those Wisps say.  I usually just nod."]="Não sei você, mas eu não entendo nem uma palavra do que dizem os fogos fatuos.",
["I don't like to be underground.  It reminds me of death."]="Não gosto de estar debaixo de terra. Lembra-me da morte.",
["I don't mind the Gnomes, but I'm always worried about tripping over one."]="Não me incomodam os gnomos, mas sempre acho que vou tropeçar com um.",
["I don't need to get funky.  I'm already there."]="Não há ninguém melhor que eu... quando se trata de brincar com a morte.",
["I don't smell that bad for a dead dude, do I?"]="Para ser um morto não hô tão mal, não é?",
["I don't think so."]="Acho que não.",
["I feel pretty, oh so pretty (spit)."]="Sinto-me bonita, muito bonita (escupe).",
["I feel very feminine, and I'll beat the crap out of anyone who disagrees."]="Eu vejo-me muito feminina e partirei as pernas a qualquer um que diga o contrário.",
["I give myself a Dutch oven pedicure every night.  I've got no foot fungus at all.  My toes are pristine."]="Cada noite faço-me a pedicura numa grande panela. Não tenho nem um fungo. Tenho os pés inmaculados.",
["I got a shrunken head.  I just came out of the pool."]="A minha cabeça ficou encolhada. Acabo de sair da piscina.",
["I got all this and personality, too."]="Além do que você vê, tenho uma grande personalidade.",
["I had an idea for a device that you could put small pieces of bread in to cook, but in the end I really didn't think there would be much of a market for it."]="Eu disse um aparelho para colocar fatias de pão e tostarlas, mas pensei que, na verdade, ninguém usaria uma coisa assim.",
["I have a number of inventions I'd like to show you back at my place."]="Tenho umas invenções em casa que gostaria de te mostrar.",
["I have no respect for people with small piercings.  I say go full hog.  Put a spear through your head."]="As pessoas com piercings pequenos não me inspiram respeito. Acho que há que ir a por todas... como se clavando uma lança em meio da cabeça!",
["I heard a knee slapper once, and skipped my kneecap right across a lake."]="A verdade é que sou tão engraçada que às vezes me parto eu sozinha.",
["I heard if you cut off an extremity, it'll regenerate a little bigger.  Don't believe it."]="Ouvi dizer que se você se cortar um membro, sai-te outra de maior tamanho. Não acredito nisso.",
["I hope you're not afraid of snakes."]="Espero que não tenha medo das cobras.",
["I hope you're well rested.  You're going to need your strength."]="Espero que você tenha descansado bem. Você precisará de toda a sua força.",
["I kill two dwarves in the morning, I kill two dwarves at night.  I kill two dwarves in the afternoon, and then I feel alright. I kill two dwarves in time of peace and two in time of war. I kill two dwarves before I kill two dwarves, and then I kill two more."]="Mato dois enanos pela manhã e à noite outros dois. Mato dois enanos à tarde e já me sinto melhor. Mato dois enanos em tempos de paz e outros dois em tempos de guerra. Mato dois enanos antes de matar dois enanos e logo depois outros dois.",
["I know.  My natural beauty is intimidating."]="Eu sei. Minha beleza natural intimida.",
["I lead the way."]="Eu vou à frente.",
["I like large posteriors, and I cannot prevaricate."]="Eu adoro os traseiros grandes. Não posso mentir.",
["I like men who aren't afraid to cry; cry uncle."]="Eu gosto dos homens que não têm medo de chorar; vamos, chora.",
["I like my ale like I like my men; dark and rich."]="Eu gosto de cerveja como gosto de homens: escuros e ricos.",
["I like my beer like I like my women; stout and bitter."]="Eu gosto da cerveja como a mulher, com corpo e amarga.",
["I like my women dumpy and droopy with halitosis."]="Adoro féminas regordetas, fofas e halitosis.",
["I like tall men."]="Eu gosto de homens altos.",
["I like to fart in the tub."]="Eu gosto de me tirar penteado na banheira.",
["I look bigger in those mirrors where things look bigger."]="Se eu me olhar num espelho de aumento, pareço muito maior.",
["I love you like a fat kid loves cake."]="Gosto de um menino gordo que gosta de bolos.",
["I must be asleep, cause you're a dream come true.  Also, I'm slightly damp."]="Tenho de estar sonhando porque és um sonho feito realidade. Além disso, sinto-me úmido.",
["I need a hero."]="Preciso de um herói.",
["I need healing!"]="Preciso que me sanem!",
["I need healing."]="Preciso que me sanem!",
["I need help!"]="Preciso de ajuda!",
["I need mana!"]="Preciso de maná!",
["I need more mana!"]="Preciso de mais maná!",
["I need some mana!"]="Preciso de maná!",
["I need to get my chest waxed again."]="Tenho que me fazer a cera no peito de novo.",
["I once laughed so hard, I milked all over the floor."]="Uma vez rejei tão forte que pringuei todo o solo de leite.",
["I owe you one."]="Eu te devo uma.",
["I require aid!"]="Preciso de ajuda!",
["I suppose so."]="Suponho que sim.",
["I thank you."]="Obrigado.",
["I think that guys just use the Emerald Dream as an excuse to avoid calling me back."]="Acho que os tios só usam o Sonho Esmeralda como uma desculpa para não me ligar novamente.",
["I think that last vendor short changed me.  Oh, that was a bad one."]="Acho que ando curto de mudança. Vale, este é muito ruim!",
["I want a man with soft hands.  Preferably four of them."]="Quero um macho com as mãos suaves. Se puder ser, com quatro mãos.",
["I will crush and destroy and... ooo... shiny..."]="Aplastarei e destruirei e... Ummm, o que gustito.",
["I will lead the way."]="Eu conheço o caminho.",
["I will return the favor."]="Vou te devolver o favor.",
["I wish you well."]="Desejo-lhe o melhor.",
["I won't bite you where it shows."]="Não te morderei onde se vê.",
["I won't fall for any bad pickup line.  You've got to try two or three, at least."]="Não vou cair aos seus pés na primeira. Você terá que tentar pelo menos duas ou três vezes.",
["I won't forget this."]="Não esquecerei.",
["I would expect the same."]="Esperaria o mesmo.",
["I would like to join a group"]="Gostaria de me juntar a um grupo",
["I'd like to give a shout out to my boys in Gnomeregan.  Keeping it real Big-T, Snoop-Pup, and Little Dees.  Y'all are short, but you're real, baby."]="Gostaria de saudar os meus colegas de Gnomeregan. Grande-T, Fisgón e Pequeno Dees... são o leite. Pequenos, mas o leite.",
["I'd like to see you in a kilt."]="Gostaria de te ver com saia.",
["I'd paint my toenails, but I'm not sure where they fell off."]="Eu pintaria as unhas, mas é que não as encontro.",
["I'll always treasure our time together."]="Aprecio muito o tempo que passamos juntos.",
["I'll give you crazy love."]="Eu te amarei como uma selvagem.",
["I'll have you know I can flatten steel with my thighs."]="Eu te informo de que sou capaz de esmagar aço com as coxas.",
["I'll lead the way."]="Eu conheço o caminho.",
["I'll miss you."]="Sentirei-te de menos.",
["I'm a force of nature."]="Sou uma força da natureza.",
["I'm also looking for a group for:"]="Também busco um grupo para:",
["I'm dead, and I'm pissed."]="Estou morto e estou farto.",
["I'm in a rotten mood."]="Hoje eu moro a cachorro morto.",
["I'm looking for a group for:"]="Procuro um grupo para:",
["I'm out of mana!"]="Não me fica maná!",
["I'm short on mana!"]="Quase não me fica maná!",
["I'm the type of girl my mother warned me about."]="Sou o tipo de garota do qual minha mãe sempre me quis afastar.",
["I'm tired of the same old bull."]="Eu me aborrece de sempre o mesmo.",
["I've discovered that getting pummeled by a blunt weapon can be quite painful."]="Descobri que uma soma de paus pode ser bastante dolorosa.",
["I've got big soulful eyes, long eyelashes, and a wet tongue.  What more could a guy want?"]="Tenho olhos grandes e enternecedores, longas páginas e a língua bem molhada. O que mais pode desejar um macho?",
["I've got no mana!"]="Não me fica maná!",
["IM Style"]="Mensagem",
["INTERNAL ERROR, DISMOUNTING A NON-PET"]="ERRO INTERNO AO DESMONTAR UM OBJETO QUE NÃO É UM ANIMAL DE ESTIMAÇÃO",
["INTERNAL ERROR, YOU DON'T HAVE A PET TO DISMOUNT"]="ERRO INTERNO. NÃO HÁ ANIMAL DE ESTIMAÇÃO PARA SAIR.",
["Icon"]="Icono",
["Icon Color"]="Cor do ícone",
["Icons in Chat"]="Ícones no chat",
["If I said you had a good body, would you hold it against me?"]="Se eu disse que gosto do seu corpo, você me daria um abraço?",
["If I wasn't purple, you'd see I was blushing."]="Se não fosse de cor roxo, você verá que eu me ruborizado.",
["If cannibalism be wrong, I don't want to be right."]="Se o canibalismo está mal, não quero ser bom.",
["If checked, invitees whom respond to this event will have their status approved automatically; otherwise, you will have to approve them manually."]="Se selecionado, o estado dos convidados que respondam a este evento irá mudar automaticamente para aprovação, se não, os terás de aprovar manualmente.",
["If checked, invitees will be unable to respond to this event."]="Se selecionado, os convidados não poderão responder a este evento.",
["If enabled, you will be able to look at your map to see the locations of certain quest objectives."]="Se estiver ativo, você poderá ver no mapa a localização de certos objetivos de missões.",
["If enabled, you will be able to review your talents in the Talent Interface before spending your talent points."]="Se estiver ativo, você poderá rever os seus talentos na interface antes de gastar os seus pontos de talento.",
["If enabled, you will only be able to receive loot by looting quest items, looting items that everyone passes on, or being given loot by the master looter."]="Se estiver ativo, só poderá receber botín saqueando objetos de missão, objetos que o resto renuncie ou recibando-o do mestre do botín.",
["If enabled, your character will automatically dismount before casting while flying."]="Se o ativas, a sua personagem vai desmontar antes de lançar um feitiço enquanto voa.",
["If enabled, your character will automatically switch between auto attack and auto shot."]="Se o ativo, a sua personagem irá alternar automaticamente entre atacar e disparar automaticamente.",
["If rot was hot, I'd be a volcano."]="Se o podre estivesse de moda, eu seria modelo.",
["If the Name Plate is displayed for your current target, show the enemy cast bar with the target's health bar in the game field."]="Se a placa de nome do seu objetivo atual for exibida, mostrar a barra de lançamento do inimigo junto à barra de saúde no campo de jogo.",
["If the sole purpose or intent of any action is to continually upset, aggravate, or otherwise annoy another player, that action may be considered physical harassment or �grief play�.  Before reporting physical harassment, make sure that the situation that is being petitioned falls outside the realm of the PvP policy (www.worldofwarcraft.com/policy/pvp.shtml). "]="É considerado abuso físico ou jogo injusto qualquer ato cujo único propósito é ofender, incordiar ou incomodar continuamente outro jogador. Antes de denunciar tal abuso, certifique-se de que a situação suscitada não está dentro da regulamentação de JcJ (www.wow-europe.com/es/policy/pvp.shtml).",
["If there is another player you have enjoyed playing with, add them to your friends list! Click on the |cffffd200Social Button|r and add them to your list of friends.|n|nYou can only add friends from your own realm."]="Se você tiver gostado de jogar com outro jogador, adicione-o à sua lista de amigos. Clique no |cffffd200botão Social|r e adicione-o à sua lista de amigos.|n|nSó pode adicionar amigos do seu mesmo reino.",
["If this is checked, sound will be recorded in the movie."]="Se estiver ativo, o som será gravado com o vídeo.",
["If this is checked, the game will offer the choice of compressing, ignoring, or deleting any pending movies when you log in."]="Se estiver ativo, quando você se ligar, o jogo irá dar- lhe a opção de comprimir, ignorar ou apagar os vídeos por- fazer.",
["If this is checked, the movie will be compressed when you stop recording. Otherwise, you will need to use the compress button to finish processing the movies."]="Se estiver ativo, o vídeo será comprimido quando parar a gravação. Se não, terá de usar o botão de comprimido para terminar o processamento dos vídeos.",
["If this is checked, you will see a movie camera icon appear on the minimap frame while recording. If the user interface is recorded, this will also appear in the movie."]="Se estiver ativo, poderá ver um ícone de câmara de vídeo que aparece na caixa do minimapa enquanto gravar. Se a interface do usuário estiver gravada, irá também aparecer no vídeo.",
["If this is checked, you will see the cursor in the movie. Regardless of this setting, you will see the cursor while playing."]="Se estiver ativo, você verá o cursor no vídeo. Se for a configuração, você verá o cursor enquanto joga.",
["If this is checked, you will see the user interface in the movie. Regardless of this setting, you will see the user interface while playing."]="Se estiver ativo, você verá a interface do usuário no vídeo. Se for a configuração, você verá a interface do usuário enquanto você joga.",
["If you are the leader of a group, this button will add your current group to the battleground queue. Your group will be guaranteed to get into the same battleground instance at the same time.  Any group member added after you click this button or a group member in a queue for another battleground will not be guaranteed entrance to the same battleground."]="Se você é o líder de um grupo, por este botão, poderá garantir um local na fila para entrar no campo de batalha. Todos os membros do grupo poderão entrar na mesma estadia ao mesmo tempo. Contudo, se você adicionar novos membros ao seu grupo ou se os membros do seu grupo já estavam em fila para outro campo de batalha, não será garantido o acesso destes membros à mesma estadia.",
["If you belong to a party, you can right-click your portrait to bring up the Party Options menu. This menu will allow you to quit the party or see what looting rules the party is using. A party leader can add or remove party members, as well as change the party's looting rules."]="Se você fizer parte de um grupo, clique com o direito do seu retrato para ver o menu de opções de grupo. Este menu permite- lhe deixar o grupo ou ver as regras de botín estabelecidas. Os líderes de grupo podem adicionar ou expulsar membros, bem como mudar as regras de botín.",
["If you defeat an enemy and see sparkles on its corpse, that means it has loot.|n|n|cffffd200Right Click|r on a creature's corpse to loot it. This will open a loot window. Then |cffffd200Right Click|r on any items in that window to move them to your backpack."]="Se você derrota um inimigo e vê que seu corpo brilha, quer dizer que tem botín.|n|n Haz |cffffd200clic direito|r no cadáver de uma criatura para despojá-lo. Isto abrirá a janela de botín. Depois, faça |cffffd200clic direito|r em qualquer objeto dessa janela para mantê-lo em sua mochila.",
["If you find yourself stuck and unable to move, please try the auto-unstuck feature prior to petitioning a GM. In most cases, this should solve the problem. Activating the auto-unstuck command will first attempt to use your hearthstone to port you back to your inn. If this is not possible, it will attempt to nudge your character out of position.\n\nPlease note this option can only be used every 5 minutes. Using the auto-unstuck option will log your character and location so that we can verify and fix the location in the future."]="Se você se queixar e não puder mover, use a ferramenta de desbloqueio automático antes de usar um MJ. Isto deverá resolver o problema na maioria dos casos. A ordem de desbloqueio automático primeiro tentará usar a sua pedra de lar para teletransportar a sua pousada. Se não for possível, tentará empurrar a sua personagem para fora dessa posição.\n\nEsta opção só pode ser usada a cada 5 minutos. A opção de desbloqueio automático irá criar um registro com a sua personagem e a sua localização para que possamos verificar e corrigir para a próxima vez.",
["If you replace this item, the following stat changes will occur:"]="Se você substituir este objeto, as seguintes alterações serão introduzidas nas estatísticas:",
["If you stray into deep and uncharted waters, you will see a Fatigue bar. If you become completely fatigued, you will begin to drown."]="Quando você se ergue em águas profundas e ignotas, aparecerá uma barra de fadiga. Quando essa barra se esvazia, você começará a afogar-se.",
["Ignore"]="Ignorar",
["Ignore List"]="Lista de Ignorados",
["Ignore Player"]="Ignorar o Jogador",
["Ignore This Slot"]="Ignorar esta opção",
["Ignore removed because the character no longer exists."]="Ignorado eliminado porque o personagem já não existe.",
["Ignored"]="Ignorado",
["Immediately report all language that is racist, extremely sexual, and/or violent; this type of language is always considered harassment."]="Informa imediatamente sobre o uso de linguagem racista, excessivamente sexual e/ou violenta. Este tipo de linguagem é considerado hostil.",
