["In my native tongue, my name means Dances with Tassels."]="Na minha língua, o meu nome significa dançar com bolas.",
["In the upper left corner of your screen is your health bar in green. When your health bar reaches zero, you will die, so be careful.|n|nBelow your health bar is a second bar representing the resource your class uses to power your special abilities, such as rage, energy or mana. Both bars will refill slowly over time."]="No canto superior esquerdo do tela aparece a sua barra de saúde verde. Quando esta barra chegar a zero, você morrerá, então tenha cuidado.|n|nBajo a sua barra de saúde há uma segunda barra que representa o recurso que usa a sua classe para suas habilidades especiais, como a ira, a energia ou o maná. Ambas as barras vão se preenchindo lentamente.",
["In-line"]="Online",
["Inactive"]="Inativo",
["Inappropriate Name"]="Nome Indenível",
["Inbox"]="Bandeja de Entrada",
["Include This Slot"]="Incluir esta opção",
["Include a message for your friend (optional)"]="Adiciona uma mensagem para o seu amigo (opcional)",
["Incoming Amount"]="Quantidade recebida",
["Incoming Whisper"]="Sussurros recebidos",
["Incoming!"]="Ememigos!",
["Incomplete"]="Incompleto",
["Incorrect party size for this arena."]="Tamanho de grupo errado para esta areia.",
["Increase multisampling to smooth out model edges. Increasing multisampling can severely reduce performance."]="Aumenta o multi-muestreo para suavizar os contornos dos modelos. Se o aumentar, poderá reduzir drasticamente o desempenho.",
["Increases Health and Mana regeneration rates. Spirit affects all\ncharacters' Mana and Hit Point regeneration rates in and\nout of combat."]="Aumenta a velocidade de regeneração de saúde e maná. O espírito afeta todas\nas velocidades de regeneração de maná e pontos de impacto em ou\nfora de combate.",
["Increases Mana points as well as chance to Critical Hit\nwith magic spells. Intellect also grants a higher chance\nto increase melee skills. (It does not affect professions\nthough.)  "]="Aumenta os pontos de maná, assim como a probabilidade de assestar golpes críticos\ncon feitiços. O intelecto também aumenta a probabilidade de\naumentar as habilidades de combate corpo a corpo. (No entanto, não afeta\na as profissões.)",
["Increases all characters’ chance to Critical Hit. The|namount of the bonus is higher per point on Rogues than|nother classes. Agility affects dodge. Rogues get more|nDodge per point of Agility than other classes. Agility|nadds directly to Armor."]="Aumenta a probabilidade de asestar um impacto crítico a todos os jogadores. A|ncantidade de bonus por ponto no pícaro|nes superior a qualquer outra classe. A agilidade afeta a capacidade de esquivar. Os pixels recebem mais|n pontos de esquivar por ponto de agilidade do que qualquer outra classe. A|nagilidade é adicionada diretamente à armadura.",
["Increases attack power with both melee and ranged weapons, and improves chance to score a critical hit with all weapons.|nIncreases armor and chance to dodge attacks."]="Aumenta o seu poder de ataque tanto com armas de corpo a corpo como à distância, e aumenta a probabilidade de assestar um golpe crítico com todas as suas armas.|nAumenta a sua armadura e a probabilidade de esquivar os ataques.",
["Increases attack power with both melee and ranged weapons, and improves the chance to score a critical hit with all weapons.|nIncreases armor and chance to dodge attacks."]="Aumenta o seu poder de ataque tanto com armas de corpo a corpo como à distância, e aumenta a probabilidade de assestar um golpe crítico com todas as suas armas.|nAumenta a sua armadura e a probabilidade de esquivar os ataques.",
["Increases attack power with melee weapons.\nIncreases the amount of damage that can be blocked with a shield."]="Aumenta o seu poder de ataque com armas corpo a corpo.\nAumenta a quantidade de dano que você pode bloquear com um escudo.",
["Increases attack power with ranged weapons.|nImproves chance to score a critical hit with all weapons.|nIncreases armor and chance to dodge attacks."]="Aumenta o seu poder de ataque com armas à distância.|nAumenta a probabilidade de asestar um golpe crítico com todas as armas.|nAumenta a sua armadura e a probabilidade de esquivar os ataques.",
["Increases health and mana regeneration rates."]="Aumenta a sua velocidade de regeneração de saúde e maná.",
["Increases health points"]="Aumenta pontos de saúde",
["Increases health points."]="Aumenta os seus pontos de saúde.",
["Increases mana points and chance to score a critical hit with spells.\nIncreases the rate at which weapon skills improve."]="Aumenta os seus pontos de maná e a probabilidade de asestar um impacto crítico com feitiços.\nAumenta a velocidade a que melhora a sua habilidade com as armas.",
["Increases texture sharpness, particularly for textures viewed at an angle.  Decrease to improve performance."]="Aumenta a nitidez das texturas, particularmente em texturas vistas de lado. Diminui este valor para aumentar o desempenho.",
["Increases the rate at which weapon skills improve."]="Aumenta a velocidade a que melhora a sua habilidade com as armas.",
["Increases the size of the Focus Frame to that of the Target Frame."]="Aumenta o quadro de abordagem ao mesmo tamanho do quadro de objetivo.",
["Increases the width of the Objectives tracker."]="Aumenta a largura do rastreador de objetivos.",
["Increases weapon damage"]="Aumenta o dano com arma",
["Indicates how smoothly the game animates. Low framerate can be improved by changing your video options."]="Se a velocidade das imagens for baixa, eu mexá- la editando as suas opções de vídeo.",
["Indicates that you are willing to heal your allies when they take damage."]="Indica que você está disposto a curar seus aliados quando eles recebem dano.",
["Indicates that you are willing to lead a group."]="Indica que você está disposto a liderar um grupo.",
["Indicates that you are willing to protect allies from harm by ensuring that enemies are attacking you instead of them."]="Ele diz que você está disposto a proteger seus aliados do dano e a ocupar-se de que os inimigos te ataquem a você e não a eles.",
["Indicates that you are willing to take on the role of dealing damage to enemies."]="Indica que você está disposto a se ocupar de infligir dano aos inimigos.",
["Indicates that you have some dungeon experience and are comfortable instructing the group in how to overcome the encounters."]="Indica que você tem alguma experiência com a masmorra e está disposto a ensinar o grupo como superar os encontros.",
