["It takes a long time after you try and use a spell or ability before the spell or ability actually occurs. Abilities may behave as if they are on cooldown even though they are not."]="Passa muito desde que você usa um feitiço ou habilidade até que esse realmente se executa. As habilidades podem agir como se estivessem em tempo de reutilização, mesmo que não o estejam.",
