["Lag is often caused by having a large number of players in one location, such as a city or Battleground. It can also be caused by high latency between your computer and the WoW servers. Submitting this report will help us detect and hopefully address lag problems you might be experiencing. \n\nWhat type of lag are you experiencing? Click on a button below to submit a report."]="Muitas vezes, o atraso provoca um grande número de jogadores num local, como uma cidade ou campo de batalha. Também provoca a latência alta entre o seu computador e os servidores de WoW. Se você enviar este relatório, você nos ajudará a detectar e, com um pouco de sorte, a tratar os problemas de atraso da sua conexão.\n\nQue tipo de atraso você está experimentando? Carregue num dos botões abaixo para enviar um relatório.",
