["Raid: "]="Banda:",
["Raids are groups of more than 5 people and are typically used to defeat unique challenges at high levels.\n\n|cffffffff- Raid members cannot earn credit toward most non-raid quests. Specifically, they will not receive non-raid quest credit for killing creatures or collecting items.\n\n- Raids grant substantially less experience for defeating monsters than normal groups.\n\n- Raids allow you to overcome challenges that might otherwise be nearly impossible.|r"]="As bandas são grupos de mais de 5 pessoas e são normalmente usadas para superar os desafios especiais dos níveis mais avançados.\n\n|cffffffff- Os membros de uma banda não obtêm benefícios da maioria das missões que não são para bandas. Particularmente, não beneficiam de missões que não são para bandas quando acabam com criaturas ou recebem objetos.\n\n- As bandas, em comparação com os grupos, diminuem notavelmente a experiência obtida quando acaba com monstros.\n\n- As bandas permitem-lhe superar desafios que são impossíveis de realizar se você não é parte de uma.|r",
