["The following are examples of Non-Quest NPC/Creep issues:"]="Abaixo estão exemplos de problemas de NPC fora de missão ou monstros errantes.",
["The following are examples of Quest/Quest NPC issues:"]="Seguem-se exemplos de problemas com NPC em missão e fora de missão:",
["The following are examples of Technical issues:"]="Seguem-se exemplos de problemas técnicos:",
