["You can eat food to gain health faster. |cffffd200Right Click|r on food to eat it."]="Para regenerar a sua saúde mais rápida, você pode comer. Faça |cffffd200clic direito|r sobre um alimento para comértelo.",
["You can enter dungeons or find groups for dungeons by using the |cffffd200Dungeon Finder|r. The Dungeon Finder is accessed from the eye button near the middle of your action bar."]="Você pode entrar em masmorras ou pesquisar grupos de masmorras usando o |cffffd200localizador de masmorras|r. Você pode acessar esse localizador no botão em forma de olho no meio da barra de ação.",
["You can equip items by first clicking the |cffffd200Character Info Button|r near the bottom of the screen, and then the |cffffd200Backpack Button|r at the bottom right of your screen.|n|nThen just drag an equippable item from your backpack onto your character."]="Para equipar objetos, primeiro clique no |cffffd200botão de informação de personagem|r perto da parte inferior do tela, e depois no |cffffd200botão da mochila|r do extremo inferior direito do tela.|n|nDepois, arrasta um objeto para equipar a partir da mochila para seu personagem.",
["You can find your corpse and resurrect at that location. Players that are level 10 or below can resurrect here with no penalty."]="Você pode buscar seu cadáver e ressuscitar lá. Os jogadores de nível 10 ou menos podem ressuscitar aqui sem penalizações.",
["You can go to your class trainer to learn new skills. |cffffd200Right Click|r on trainers to talk to them.|n|nTrainers are found in many towns or cities and always in your starting area. You may have to search around a little to find your trainer."]="Você pode dirigir-se ao seu instrutor de classe para aprender novas habilidades. Faça |cffffd200clic direito|r em um instrutor para falar com ele.|n|nOs instrutores encontram-se em muitos povos ou cidades e também em sua área de início. Talvez você deva procurar um pouco para encontrar o instrutor que procura.",
["You can invite another player to your group by |cffffd200Right Clicking|r their portrait and selecting the |cffffd200Invite|r option from the popup menu.|n|nYou can leave a group by Right Clicking on your own portrait and choosing the option to leave the party."]="Você pode convidar outros jogadores a se juntar ao seu grupo fazendo |cffffd200clic direito|r sobre seu retrato e seleccionando a opção |cffffd200Invitar|r do menu emergente.|n|n|n pode deixar um grupo clicando direito sobre seu retrato e seleccionando a opção para deixar o grupo.",
["You can learn a new talent in the talent interface.|n|nOpen the talents page by clicking the pulsing |cffffd200Talents Button|r on your action bar."]="Para aprender novos talentos existe uma interface especial.|n|nAbre a página de talentos clicando no |cffffd200botão de talentos|r intermitente de sua barra de ação.",
["You can look at your reputation with different groups in the world under the Reputation tab.|n|nClick on the |cffffd200Character Info Button|r to find the Reputation tab."]="Você pode ver sua reputação com os diferentes grupos do mundo da página de reputação.|n|n Faça clique no |cffffd200botão de informação de personagem|r para ver a página de reputação.",
["You can move spells and abilities to your action bar by clicking the |cffffd200Spellbook & Abilities Button|r at the bottom center of the screen and then dragging the ability icon to your action bar.|n|nYou can also use a spell or ability from the Spellbook directly by clicking on it."]="Você pode mover feitiços e habilidades para a sua barra de ação carregando o |cffffd200botão do livro de feitiços e habilidades|r que se encontra na parte inferior central do tela e depois arrastando o ícone da habilidade até a sua barra de ação.|n|nTambém pode usar um feitiço ou uma habilidade diretamente do livro de feitiços clicando nele.",
