["You can press the |cffffd200Spacebar|r to make your character jump. You can use jumping to get past obstacles or just for fun."]="Carregue na |cffffd200barra espaciadora|r para que seu personagem salte. Salta para superar obstáculos ou simplesmente para divertir-se.",
["You can respond to that player by hitting the R key and then typing a message, or by typing /tell <theirname> and then the message."]="Para responder a um jogador, clique na tecla R e escreva a mensagem, ou escreva /contar <nomejugador> e depois a mensagem.",
["You can send a message by hitting the Enter key, typing a message, and then hitting Enter again. Other players nearby will hear what you say."]="Para enviar uma mensagem, carregue na tecla Intro, escreva algo e volte a carregar em Intro. Os jogadores que estiverem perto ouvirão o que você disser.",
["You can turn your character by |cffffd200holding the Right Mouse Button|r and moving the mouse.|n|nYou can look around by holding the Left Mouse Button and moving the mouse."]="Você pode rodar para o seu personagem se |cffffd200mantés carregando o botão direito do rato|r e o moves.|n|n pode rodar a vista da câmara se você mantiver o botão esquerdo do rato e o mover.",
