["You feel completely smashed."]="Você está completamente bêbado.",
["You feel drunk.  Woah!"]="Que apaga, saia!",
["You feel exhausted."]="Sentes muito cansaço.",
["You feel normal."]="Você se sente normal.",
["You feel rested."]="Não se sente cansaço.",
["You feel sober again."]="Você vai se sentir sumário.",
["You feel tipsy.  Whee!"]="Que tonturas,hip, hip!",
["You feel tired."]="Sentes cansaço.",
["You feel well rested."]="Você se sente cheio de energia.",
["You go with me."]="Tu, vem comigo.",
["You had me at zug zug."]="Sinto-me totalmente zug zug zug.",
["You have accepted an elite quest. Such quests are best undertaken in a group, for they will take you into areas inhabited by elite creatures.|n|nElite creatures are significantly tougher than normal monsters; however, they are worth more experience. You can tell an elite creature by the golden dragon border around its portrait."]="Você aceitou uma missão de elite. Estas missões são resolvidas melhor em grupo, pois levar-te-ão a regiões habitadas por criaturas de elite também.|n|nLas criaturas de elite são bastante mais fortes que os monstros normais. No entanto, também ganharás mais experiência se as derrotas. Você reconhecerá uma criatura de elite pelo marco dourado de dragão que rodeia seu retrato.",
["You have already been invited into a guild."]="Já te convidou para uma guild.",
["You have already been invited into an arena team."]="Já te convidaram para uma equipe de areia.",
["You have already learned the spell"]="Já aprendeu esse feitiço",
["You have already signed that charter."]="Já assinou esses estatutos.",
["You have an active summon already"]="Já tem uma invocação ativa",
["You have an open ticket."]="Você tem aberta uma consulta.",
["You have attempted too many group actions in a short period of time.  Please wait momentarily before attempting further group actions."]="Você tentou fazer demasiadas ações de grupo em um curto período de tempo. Espere um pouco antes de tentar outra ação de grupo.",
["You have attracted the attention of a hostile creature.|n|nA red glow means the creature is attacking you. A yellow glow means you are in danger of being attacked. An orange glow means the creature is attacking you, but may soon change targets."]="Você chamou a atenção de uma criatura hostil.|n|nUm brilho vermelho significa que a criatura está a atacar você. Um brilho amarelo significa que você está em perigo de ser atacado. Um brilho laranja significa que a criatura está a atacar você, mas poderia mudar de objetivo em qualquer momento.",
["You have beautiful skin; no maggot holes at all."]="Você tem uma pele preciosa. Você não tem nem um buraco de verme.",
["You have been chosen to fill out a GM survey."]="Convidamos você a participar de uma pesquisa sobre os MJ.",
["You have been inactive for some time and will be logged out of the game. If you wish to remain logged in, hit the cancel button."]="Você se desligará do jogo, porque você está inativo durante algum tempo. Se quiser continuar conectado, carregue no botão Cancelar.",
["You have been kicked out of the guild."]="Eles te expulsaram da guild.",
["You have been removed from a PVP queue because another player has granted you a level"]="Você foi removido de uma cauda de JcJ porque outro jogador lhe deu um nível",
["You have been removed from a PVP queue because you have changed your XP gain settings"]="Você foi removido de uma fila de JcJ porque você mudou seus ajustes de obtenção de experiência",
["You have been removed from a PvP Queue because you changed your faction."]="Ele foi removido de uma cauda de JcJ porque você mudou de facção.",
["You have been removed from the Dungeon queue because someone in your party did not accept the invitation."]="Você foi removido da fila da masmorra porque alguém em seu grupo não aceitou o convite.",
["You have been removed from the Dungeon queue because you did not accept the invitation."]="Você foi removido da fila da masmorra porque não aceitou o convite.",
["You have been removed from the group."]="Eles te expulsaram do grupo.",
["You have completed that daily quest today."]="Você completou essa missão diária hoje.",
["You have completed that quest."]="Você completou essa missão.",
["You have completed your first quest! To collect your reward, you need to turn in the quest to a specific quest giver. Usually this is the same questgiver who gave you the quest.|n|nYou can see nearby questgivers as |cffffd200?|r on your minimap in the upper right of your screen. |cffffd200Right Click|r on a quest giver to talk to him or her."]="Você acaba de completar sua primeira missão! Para recolher a recompensa, você deve voltar até um atribuídor de missões específicas, que normalmente é o mesmo que lhe atribuiu a missão.|n|nEn um minimapa situado no canto superior direito do tela, você poderá ver os alocados de missões mais próximos assinalados com o símbolo |cffffd200?|r. Haz |cffffd200clic direito|r em um alocador de missões para falar com ele.",
["You have died.  Release spirit to enter Spectator Mode."]="Você morreu. Liberte o seu espírito para passar ao modo espectador.",
["You have died. Release to the nearest graveyard?"]="Você morreu. Você deseja reaparecer no cemitério mais próximo?",
["You have disbanded the guild."]="Você dissolveu a guild.",
["You have entered too many instances recently."]="Você entrou em muitas estadias ultimamente.",
["You have exited the battle for Wintergrasp."]="Você saiu da batalha pela Conquista do Inverno.",
["You have gained access to the totem bar! You will gain an action button on this bar whenever you gain access to a new totem element.|n|nThis bar can hold one totem spell per totem element. At higher level you will gain the ability to drop multiple totems at once."]="Você conseguiu acessar a barra de tótems! Cada vez que você acessar um novo item de tótem você terá um botão de ação nesta barra. |n|nLa barra pode conter um feitiço de tótem por cada item. Quando você chegar a maior nível ganhará a habilidade de lançar vários tótems ao mesmo tempo.",
["You have joined"]="Você se juntou",
["You have joined a raid group."]="Você se juntou a um grupo de raid.",
["You have joined a raid group: a group with an increased limit of 40 members, though usually 10 or 25. Raid groups are necessary to enter the most challenging dungeons or to defeat the most powerful enemies, typically at high level.|n|n|cffff2020While in a raid group, you will not earn credit towards most quests. To leave a raid group, Right Click on your character portrait and select Leave party.|r"]="Você se juntou a uma banda: é um grupo com um limite superior de até 40 pessoas, embora normalmente seja de 10 ou 25. As bandas são necessárias para acessar as masmorras mais desafiadores ou para derrotar os inimigos mais poderosos, geralmente a níveis altos.|n|n|cffff2020 Enquanto estiver em uma banda, não serão validados os objetivos da maioria das missões. Para deixar uma banda, clique direito sobre o retrato de sua personagem e selecione Deixar o grupo.|r",
["You have joined the guild."]="Você se juntou a uma guild.",
["You have learned a new spell or ability! Use the |cffffd200Spellbook & Abilities Button|r near the bottom of your screen to open your Spellbook. |cffffd200Left Click and drag|r a spell or ability to move it to your Action Bar.|n|nThe Spellbook is organized by category, as indicated by the tabs sticking out from the right side of the book."]="Você aprendeu um feitiço ou uma habilidade nova! Use o botão do |cffffd200libro de feitiços e habilidades|r que você vai encontrar na parte inferior do tela para abrir o livro de feitiços. Faça |cffffd200clic esquerdo e arrasta|r um feitiço ou uma habilidade para movê-lo para a barra de ação.|n|nEl livro de feitiços está organizado por categorias, como indicam as páginas que sobressaem da parte direita do livro.",
["You have learned everything from that book"]="Você aprendeu todo esse livro",
["You have left the guild."]="Você abandonou a guild.",
["You have left the raid group."]="Você abandonou o grupo de raid.",
["You have no friend requests"]="Não há pedidos de amizade",
["You have no recently updated stats"]="Não tem estatísticas actualizadas recentemente",
["You have no target or your target is too far away."]="Você não tem objetivo ou está longe demais.",
["You have no target."]="Você não tem objetivo.",
["You have nobody to reply to yet."]="Ainda não tens ninguém a quem responder.",
["You have not completed the required quest."]="Você não completou a missão necessária.",
["You have not earned any achievements recently"]="Não ganhou nenhum sucesso recentemente",
["You have not earned enough levels to grant any more levels"]="Para dar mais níveis, você precisa ganhar mais",
["You have not spent any talent points."]="Não gastou nenhum ponto de talento.",
["You have obtained a ranged weapon. To use it, first equip the weapon by opening your |cffffd200Character Info|r and your |cffffd200Backpack|r and dragging the item onto your character.|n|nThen, open up your |cffffd200Spellbook|r and drag the |cffffd200Shoot|r or |cffffd200Throw|r ability onto your action bar.|n|nOnly hunters, warriors and rogues may use ranged weapons. Mages, priests and warlocks may use wands."]="Você fez com uma arma à distância. Para usá-la, deve equipar-a (abre a |cffffd200Informações do personagem|r e a |cffffd200Mochila|r e arrasta o objeto até a sua personagem).|n|nDepois, abre o seu |cffffd200Livro de feitiços|r e arrasta a habilidade |cffffd200Disparar|r ou |cffffd200Lanzar|r a sua barra de ação.|n|nTan só os caçadores, guerreiros e pícaros podem usar armas à distância, enquanto os mágicos, sacerdotes e brujos podem usar varitas.",
["You have pending calendar invites."]="Você tem convites pendentes no calendário.",
["You have reached the in-game cap of unique mail recipients"]="Não pode enviar a mesma mensagem para mais receptores",
["You have received a new friend request."]="Você recebeu um novo pedido de amizade.",
["You have received a ticket response. Click here to read it."]="Você recebeu uma resposta à sua consulta. Clique aqui para lê-la.",
["You have requested a duel."]="Você retou alguém para um duelo.",
["You have six different smiles; one for when you're angry, one for when you tear flesh, one for when you chew flesh, one for when you loot bodies, one for when you skin game, and one for when you want to kill something."]="Você tem seis sorrisos diferentes. Uma para quando está brava, outra para quando rasgas carne, outra para quando masticas carne, outra para quando despojas corpos, outra para quando dessollas animais e a última para quando quer matar alguém.",
["You have the maximum number of those gems in your inventory or socketed into items."]="Você tem o número máx. dessas gemas no seu inventário ou em ranhuras de objetos.",
["You have the maximum number of those gems socketed into equipped items."]="Você já introduziu o número máximo permitido dessas gemas nos objetos que você tem equipados.",
["You have to be standing to attack anything!"]="Para poder atacar você tem que estar de pé!",
["You have to be unsheathed to do that!"]="Para fazer isso você tem que desenvainar.",
["You have too many of a unique item."]="Você tem demasiadas unidades de um objeto.",
["You have too many of that item already"]="Já tens demasiados objetos iguais",
["You have too many pets already"]="Já tens muitos animais",
["You have unread mail"]="Você tem mensagens sem ler",
["You haven't reached that taxi node on foot yet!"]="Ainda não chegou a pé à escala!",
["You haven't selected a champion"]="Não seleccionou um Campeão",
["You know I have to keep moving at night or I'll disappear."]="Você sabe? Não posso deixar de me mover nem à noite ou desapareço.",
["You know how hard it is to get your groove on with the spirit of your great grandmother looking over you?"]="Você sabe o quão difícil é sentir-se leve quando você tem o espírito de sua tatarabuela sobre as costas todo dia?",
["You know those Ancient Protectors in Darnassas?  They're not that old."]="Sabem? Esses protetores ancestrais de Darnassus não são tão velhos.",
["You know, I really wish I had a garden where I could put a couple of human statues."]="Você sabe? Eu adoraria ter um jardim onde colocar umas duas estátuas de humanos.",
["You know, Taurens are born hunters.  You ever see a Tauren catch a salmon out of a stream?  It really is quite exciting.  And, have you ever seen a Tauren stalk a python?  'Course you haven't.  That's because Taurens are so adept at blending in with their surroundings."]="Sabem, os tauren nascem caçadores. Você já viu um tourão pegar um salmão de um rio? É realmente emocionante. E... você viu um tourã espreitando uma cobra? É claro que não o viu. Isso é porque os tauren são especialistas em camuflar-se com o ambiente.",
["You know, Wisps are actually pretty useful for personal hygiene."]="Sabe? Os fogos fatuos são bastante úteis para a higiene pessoal.",
["You know, older bulls really only have one function."]="Você sabe? Os touros velhos só servem para uma coisa.",
["You know, once you're dead, nothing smells bad anymore.  Rotten eggs?  No problem.  Dead fish?  Like a spring breeze."]="Sabe? Quando está morto, nada cheira mal. Você podes podres? Não há problema. Pescado morto? Como uma brisa de primavera.",
["You know, squirrels can be deadly when cornered."]="Você sabe que um esquilo acorralado pode ser mortal.",
["You leave the group."]="Deixa o grupo.",
["You look pretty.  I like your hair.  Here's your drink.  Are you ready now?"]="Você está bonita. Eu gosto do seu cabelo. Aí você tem a sua bebida. Você já está pronta?",
["You look pretty.  Pretty tasty."]="Você está para comer. Com batatas.",
["You may find that a solution for your issue has already been posted on the Technical Support Forum, located on the World of Warcraft site at:\n\nwww.worldofwarcraft.com\n\nIf your technical issue is not addressed by the solutions posted there, please contact our Technical Support Department:\n\nBy Phone at:  (949) 955-1382\nBy Web at: http://us.blizzard.com/support/index.xml?gameId=11\nBy Email at:  wowtech@blizzard.com"]="Você pode encontrar uma solução já publicada para o seu problema no fórum do Serviço de Assistência Técnica no site do World of Warcraft:\n\nwww.wow-europe.com/es/\n\nSi o seu problema técnico não aparece lá, por favor, entre em contato com o nosso Serviço de Assistência Técnica:\n\nPor telefone: 800 099 812 (pulsa 4 para espanhol)\nA através do nosso site: http://www.wow-europe.com/es/support/technical.html\nPor e-mail: wowtechEU@blizzard.com.",
["You may not bite other vampires."]="Não pode morder outros vampiros.",
["You may not create custom channels with profane names."]="Não pode criar canais personalizados com nomes que contenham linguagem adulta.",
["You may not list yourself in the Raid Browser while you are queued for a Dungeon."]="Você não pode se apontar no Buscador de banda enquanto está em fila para uma masmorra.",
["You may not queue for a Dungeon while you are listed in the Raid Browser."]="Você não pode se colocar em fila para uma masmorra enquanto você está apontado no Buscador de banda.",
["You may not queue for this dungeon."]="Você não pode se pôr em fila para esta masmorra.",
["You may not queue for this."]="Não podes te pôr em fila para isto.",
["You may not queue while one or more of your team members is under the effect of restricted play."]="Você não pode se colocar à cauda enquanto um ou mais membros da sua equipe estão sob os efeitos de jogo restrito.",
["You may not trade an item with a temporary enhancement."]="Você não pode comer com um objeto que tenha uma melhora temporária.",
["You may only call down a Wintergarde Gryphon in Wintergarde Keep or the Carrion Fields."]="Você só pode invocar uma torneira de Hibergarde na Fortaleza de Hibergarde ou em Os Campos de Carroña.",
["You may only call down a stampede on Harold Lane."]="Você só pode invocar uma estampida sobre Harold Sendero.",
["You may only call for the aid of a Wyrmrest Vanquisher in Wyrmrest Temple, The Dragon Wastes, Galakrond's Rest or The Wicked Coil."]="Você só pode pedir ajuda a um vencedor do Reposo do Dragão no Templo do Reposo do Dragão, o Baldiu do Dragão, Reposo de Galakrond ou La Espiral Maldita.",
["You may only trade bound items to players that were originally eligible to loot the item"]="Você só pode comer objetos ligados a jogadores que, desde o início, reunissem os requisitos para ficar o objeto",
["You may only trade conjured items to players from other realms"]="Os objetos mágicos só podem ser comidos com personagens de outros reinos",
["You may only use the Pouch of Crushed Bloodspore on Gammothra or other magnataur in the Bloodspore Plains and Gammoth."]="Você só pode usar a saia de sanguiesporas machacadas com Gammothra ou outros magnatauros nas Llanuras Sanguiespora e em Gammoth.",
["You may want to invite other players to team up with you to more easily overcome your enemies.|n|nMany difficult quests can be quickly completed in a group, as quest credit is shared by the group. Moreover, groups earn bonus experience, relative to solo players."]="Você pode convidar outros jogadores a unir forças contigo para derrotar inimigos com mais facilidade.|n|n|nMuitas missões difíceis se completam facilmente em grupo e o crédito da missão se divide entre seus membros. Além disso, os grupos ganham bonus de experiência que os jogadores em solitário não.",
["You move me."]="Me matem.",
["You must advance to a higher level."]="Você deve subir a um nível mais alto.",
["You must be a guild master to purchase a tabard, but feel free to browse."]="Para comprar um tabardo deve ser o Mestre de uma guild, embora você possa olhar também.",
["You must be behind your target."]="Você deve estar atrás do seu objetivo.",
["You must be close to a marked tree."]="Você deve estar perto de uma árvore marcada.",
["You must be closer to a plague wagon in order to drop off your 7th Legion Siege Engineer."]="Você deve estar mais perto de um vagão de peste para soltar seu engenheiro de cerco da sétima Legião.",
["You must be closer to a sinkhole to use your map."]="Você tem que estar mais perto de um sumidero para usar o seu mapa.",
["You must be closer to the buoy!"]="Você deve estar mais perto da boia!",
["You must be facing the corpse to loot it."]="Para despojar um cadáver, você tem que ter isso em frente a você.",
["You must be flagged for PvP in order to help capture this objective."]="Você deve estar marcado como JcJ para ajudar a capturar este objetivo.",
["You must be in a raid group to enter this instance."]="Você deve pertencer a um grupo de raid para entrar nesta estadia.",
["You must be in front of your target."]="Você deve estar diante de seu objetivo.",
["You must be in stealth mode."]="Você deve estar em modo sigilo.",
["You must be joking."]="Nem a brincar.",
["You must be near the Maiden of Winter's Breath Lake."]="Você deve estar perto da donzela do Lago Aliento Invernal.",
["You must be sitting in a barber chair"]="Você deve estar em um poltrona de barbeiro",
["You must be standing to do that"]="Você deve estar de pé para fazê-lo",
["You must be the party leader to interact with the meeting stone"]="Para interagir com uma rocha de encontro, você tem que ser o líder do grupo",
["You must be unsheathed"]="Você deve desenvainar",
["You must be within range of a Helpless Wintergarde Villager."]="Você tem que estar ao alcance de um habitante de Hibergarde indefenso.",
["You must choose a category to submit your bug/suggestion."]="Para enviar um relatório de erro ou uma sugestão, você deve escolher a categoria.",
["You must choose a reward."]="Você tem que escolher uma recompensa.",
["You must either be in a party or currently be looking for a group to join Looking For More."]="Você deve estar em um grupo ou procurar um grupo para se unir a Pesquisar mais.",
["You must enter text for your ticket."]="Você tem que escrever algo na consulta.",
["You must enter the instance to recover your corpse"]="Para recuperar seu cadáver, você terá que entrar na estadia",
["You must equip that item to use it."]="Para usá-lo, você deve equipar.",
["You must first select a Proto-Drake Egg."]="Antes você deve selecionar um ovo de protodraco.",
["You must have The Burning Crusade expansion installed to access this area."]="Você deve ter instalado a expansão The Burning Crusade para acessar esta área.",
["You must have The Wrath of the Lich King expansion installed to access this area."]="Para acessar esta área, você tem que ter a expansão The Wrath of the Lich King instalada.",
["You must have a Fire Totem active."]="Você deve ter um tótem de Fogo ativo.",
["You must have a demonic circle active."]="Você deve ter um círculo demoníaco ativo.",
["You must have a lance equipped."]="Você deve ter uma lança equipada.",
["You must meet the min bid."]="Você deve alcançar a proposta mínima.",
["You must obtain better gear."]="Você deve obter melhor equipamento.",
["You must promote a new Guild Master using /gleader before leaving the guild."]="Antes de abandonar a guild você deve delegar seu posto de Mestre em alguém mediante o comando /hmaestro.",
["You must promote a new team captain using /teamcaptain before leaving the team."]="Para promover um novo capitão de equipe, usa o comando /equipacapitan antes de deixar a equipe.",
["You must purchase that bag slot first"]="Primeiro você deve comprar o espaço para essa bolsa.",
["You must reach level 58 to use this portal."]="Você deve atingir o nível 58 para usar este portal.",
["You must repair that item before you auction it."]="Você deve reparar o objeto se você quer leilões.",
["You must repair that item's durability to use it."]="Você deve restaurar a durabilidade do objeto para usá-lo.",
["You must select at least one role."]="Você deve selecionar pelo menos uma função.",
["You must specify a loot master."]="Você deve especificar um mestre despojador.",
["You must specify a target: /<command> <target's name>"]="Você deve especificar um objetivo: /<orden> <nome do objetivo>",
["You must target a Fjord Hawk."]="Você deve apontar um halcón de fiordo.",
["You must target a Fjord Turkey."]="Você deve apontar um perus de fiorde.",
["You must target a weakened chill nymph."]="Você deve apontar uma ninfa arrepia debilitada.",
["You must unequip that item first"]="Primeiro você deve tirar esse objeto",
["You need Evasive Charges"]="Precisas de cargas evasivas",
["You need more signatures."]="Você precisa de mais assinaturas.",
["You need to be closer to interact with that target."]="Você tem que estar mais perto para interagir com esse objetivo.",
["You need to be in a party to use a meeting stone"]="Você deve estar em um grupo para usar uma rocha de encontro",
["You need to be standing to go anywhere."]="Para ir a qualquer parte você precisa estar de pé.",
["You need to be standing up to loot something!"]="Para despojar um cadáver, você tem que estar de pé.",
["You need to have at least a level 20 character on your account."]="Você deve ter pelo menos um personagem de nível 20 em sua conta.",
["You now have a keyring to hold your keys.This |cffffd200Keyring Button|r appears to the left of your bags on your action bar."]="Agora você conta com um chaveiro para levar suas chaves. Você verá o |cffffd200botão do Chavero|r à esquerda das bolsas, na sua barra de ação.",
["You really want the item."]="Você quer o objeto de verdade.",
["You received a bag. Now you will be able to carry more items.|n|nMove the bag to an empty bag space next to your backpack. Click on a bag to open it."]="Você recebeu um saco. Você agora poderá levar mais objetos.|n|nColoca a bolsa em um espaço de saco vazio junto à sua mochila. Clique acima para abri-la.",
["You recently deserted a Dungeon Finder group and may not queue again for:"]="Você desertou recentemente de um grupo de busca de masmorras e não pode voltar a entrar na fila até:",
["You recently queued for a Random Dungeon.\nYou may queue for another in:"]="Recentemente, você esteve em fila para uma masmorra aleatória.\nPodes voltar a colocar-se em fila em:",
["You scratch my back, I scratch yours."]="Tu me rascas as costas e eu te a coçar a ti.",
["You shall be granted the title:"]="É-lhe dado o título de:",
["You should be proud."]="Você é incrível.",
["You stay here."]="Você fica aqui.",
["You want to Greed the item, but you want it disenchanted if you win the roll."]="Você quer escolher Codicia, mas se você quiser que o objeto seja desencante.",
["You were Away for a ready check"]="Estavas no modo Ausente durante uma verificação",
["You were not referred by that player"]="Esse jogador não o recruta",
["You will also receive the following rewards. They scale with the number of random players included in your group:"]="Você também receberá as seguintes recompensas. Eles irão aumentar de acordo com o número de jogadores aleatórios incluídos no seu grupo:",
["You will also receive:"]="Também receberá:",
["You will be able to choose one of these rewards:"]="Você pode escolher uma dessas recompensas:",
["You will be unflagged for PvP combat after five minutes of non-PvP action in friendly territory."]="Você perderá a marca de combate JcJ se você passar 5 minutos ou mais em um território amigo sem ação JcJ.",
["You will learn how to create:"]="Você aprenderá a criar:",
["You will learn:"]="Você vai aprender:",
["You will lose any unsaved changes if you switch between general and character specific key bindings."]="Se você mudar entre a configuração geral do teclado e a específica de um personagem, você perderá todas as mudanças que você não tenha guardado.",
["You will lose your initial deposit by canceling this auction."]="Você perderá o seu depósito inicial se você cancelar o leilão.",
["You will no longer be able to view your response message if you mark it as read. Are you sure you want to mark your message read?"]="Você não poderá ver a sua mensagem de resposta se a marca como lida. Tem a certeza que deseja marcar a mensagem como lida?",
["You will no longer be able to view your response message if you request more help. Are you sure you want to open a follow-up ticket?"]="Você não poderá ver a sua mensagem de resposta se você pedir mais ajuda. Tem a certeza que deseja enviar um novo pedido relacionado?",
["You will receive:"]="Você receberá:",
