["You'd like to run your hands through my beard, wouldn't you?"]="Sei que adoraria tocar a barba. A que sim?",
["You'll do.  Let's go."]="Eu me conformarei com você. Vamos.",
["You'll take the item, but only if nobody else really wants it."]="Você quer o objeto, mas só se ninguém o quer de verdade.",
